export declare const panelStyle = "html{scroll-behavior:smooth}body{max-width:1120px!important}nav{display:flex;gap:8px;flex-wrap:wrap;position:sticky;top:0;background:#f6f8fbf2;padding:12px 0;z-index:2}nav a{color:#345280;text-decoration:none;padding:6px 10px;background:#e8eef9;border-radius:8px}section{scroll-margin-top:90px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.grid label{font-size:14px}textarea,select{font:inherit;width:95%;padding:9px;border:1px solid #bbc7d9;border-radius:6px;box-sizing:border-box}textarea{min-height:85px}input[type=checkbox]{display:inline;width:auto;margin:0 8px 0 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.7 system-ui;background:#f5f7fc;padding:14px;border-radius:8px}.item{border-top:1px solid #e3e8f2;padding:12px 0;overflow-wrap:anywhere}.item button{padding:4px 10px;font-size:14px}.muted{color:#69778b;font-size:14px}.danger{background:#a33340!important}.badge{color:#245fca;font-size:13px}h1{letter-spacing:-.7px}h3{font-size:16px}details{margin:14px 0}summary{cursor:pointer}button{transition:background .15s}button:hover{filter:brightness(.95)}#panel-summary{border-left:4px solid #245fca} @media(max-width:600px){body{padding:0 14px!important;margin:18px auto!important}section{padding:16px!important}nav{position:static}}";
export declare const panelSections = "<nav aria-label=\"\u63D2\u4EF6\u529F\u80FD\"><a href=\"#overview\">\u603B\u89C8</a><a href=\"#proactive-panel\">\u4E3B\u52A8\u8054\u7CFB</a><a href=\"#computer-panel\">\u7535\u8111\u611F\u77E5</a><a href=\"#personality-panel\">\u6027\u683C</a><a href=\"#memory-panel\">\u8BB0\u5FC6</a><a href=\"#tasks-panel\">\u63D0\u9192</a><a href=\"#files-panel\">\u5BFC\u5165\u5BFC\u51FA</a><a href=\"#cloud-panel\">\u767E\u5EA6\u7F51\u76D8</a><a href=\"#maintenance-panel\">\u7EF4\u62A4\u4E0E\u8BCA\u65AD</a></nav>\n<section id=\"overview\"><h2>\u8FD0\u884C\u603B\u89C8</h2><label>\u67E5\u770B\u54EA\u4E2A\u89D2\u8272\u548C\u4F1A\u8BDD<select id=\"panel-conversation\" aria-label=\"\u89D2\u8272\u548C\u4F1A\u8BDD\"></select></label><pre id=\"panel-summary\">\u6B63\u5728\u8BFB\u53D6\u63D2\u4EF6\u72B6\u6001\u2026</pre><div><button class=\"command secondary\" data-action=\"mood\">\u60C5\u7EEA\u4E0E\u5173\u7CFB\u8BE6\u60C5</button><button class=\"command secondary\" data-action=\"why\">\u6700\u8FD1\u6001\u5EA6\u53D8\u5316\u539F\u56E0</button></div><pre id=\"panel-result\" hidden></pre></section>\n<section id=\"proactive-panel\"><h2>\u4E3B\u52A8\u627E\u4F60\u804A\u5929</h2><p id=\"proactive-explanation\"></p><button class=\"command\" data-action=\"proactive-on\">\u5F00\u542F\u4E3B\u52A8\u8054\u7CFB</button><button class=\"command secondary\" data-action=\"proactive-off\">\u6682\u505C\u4E3B\u52A8\u8054\u7CFB</button><button class=\"command secondary\" data-action=\"preview\">\u9884\u89C8\u5408\u9002\u7684\u8BDD\u9898</button><button class=\"command secondary\" data-action=\"scan\">\u73B0\u5728\u68C0\u67E5\u4E00\u6B21</button><p class=\"muted\">\u68C0\u67E5\u4F1A\u6309\u5F53\u524D\u89C4\u5219\u9009\u62E9\u8BDD\u9898\u5E76\u5B89\u6392\u53D1\u9001\uFF1B\u9884\u89C8\u53EA\u751F\u6210\u8349\u7A3F\u3002\u6CA1\u6709\u771F\u5B9E\u7EBF\u7D22\u65F6\u4F1A\u4FDD\u6301\u5B89\u9759\u3002</p>\n<div class=\"grid\"><label>\u57FA\u7840\u6BCF\u65E5\u6700\u591A\u6761\u6570<input id=\"daily-limit\" type=\"number\" min=\"0\" max=\"24\"></label><label>\u57FA\u7840\u95F4\u9694\uFF08\u5206\u949F\uFF09<input id=\"min-gap\" type=\"number\" min=\"10\" max=\"1440\"></label><label>\u6BCF\u9694\u51E0\u5206\u949F\u68C0\u67E5<input id=\"check-minutes\" type=\"number\" min=\"1\" max=\"60\"></label><label>\u51E0\u6761\u672A\u56DE\u590D\u540E\u6682\u505C<input id=\"unanswered\" type=\"number\" min=\"1\" max=\"5\"></label><label>\u9759\u9ED8\u5F00\u59CB<input id=\"quiet-start\" type=\"time\"></label><label>\u9759\u9ED8\u7ED3\u675F<input id=\"quiet-end\" type=\"time\"></label></div>\n<label><input id=\"adaptive\" type=\"checkbox\">\u597D\u611F\u9AD8\u4E14\u6027\u683C\u6D3B\u6CFC\u65F6\uFF0C\u9002\u5EA6\u589E\u52A0\u4E3B\u52A8\u8054\u7CFB</label><div class=\"grid\"><label>\u589E\u52A0\u540E\u6BCF\u65E5\u6700\u591A\u6761\u6570<input id=\"adaptive-max\" type=\"number\" min=\"0\" max=\"24\"></label><label>\u589E\u52A0\u540E\u6700\u77ED\u95F4\u9694\uFF08\u5206\u949F\uFF09<input id=\"adaptive-gap\" type=\"number\" min=\"10\" max=\"1440\"></label></div><pre id=\"frequency-explanation\"></pre>\n<h3>\u5174\u8DA3\u4E0E\u5206\u4EAB</h3><label>\u89D2\u8272\u81EA\u5DF1\u7684\u5174\u8DA3\uFF08\u6BCF\u884C\u4E00\u4E2A\uFF09<textarea id=\"model-interests\" placeholder=\"\u4F8B\u5982\uFF1A\u5929\u6587\u3001\u72EC\u7ACB\u6E38\u620F\u3001\u5496\u5561\"></textarea></label><label>\u5141\u8BB8\u8BFB\u53D6\u7684\u7F51\u9875\u6216 RSS \u6765\u6E90\uFF08\u6BCF\u884C\u4E00\u4E2A HTTPS \u5730\u5740\uFF0C\u6700\u591A 4 \u4E2A\uFF09<textarea id=\"share-sources\" placeholder=\"\u586B\u5199\u4F60\u613F\u610F\u8BA9\u5B83\u8BFB\u53D6\u7684\u5185\u5BB9\u6765\u6E90\"></textarea></label><p class=\"muted\">\u4F1A\u540C\u65F6\u53C2\u8003\u8BB0\u5FC6\u4E2D\u4F60\u7684\u504F\u597D\u548C\u8FD9\u91CC\u7684\u89D2\u8272\u5174\u8DA3\uFF1B\u5206\u4EAB\u4FDD\u7559\u6765\u6E90\u94FE\u63A5\uFF0C\u8BFB\u53D6\u5931\u8D25\u5C31\u8DF3\u8FC7\u3002</p><button id=\"save-settings\">\u4FDD\u5B58\u4E3B\u52A8\u8054\u7CFB\u4E0E\u7535\u8111\u611F\u77E5\u8BBE\u7F6E</button><details><summary>\u6700\u8FD1\u7684\u8BDD\u9898\u673A\u4F1A</summary><div id=\"opportunity-list\"></div></details><details><summary>\u5728\u591A\u53F0\u7535\u8111\u4F7F\u7528</summary><p>\u540C\u65F6\u53EA\u6709\u9009\u5B9A\u7684\u4E00\u53F0\u7535\u8111\u8D1F\u8D23\u4E3B\u52A8\u53D1\u9001\u3002\u63A5\u7BA1\u524D\u5148\u5728\u65E7\u7535\u8111\u6682\u505C\uFF0C\u907F\u514D\u79BB\u7EBF\u671F\u95F4\u91CD\u590D\u8054\u7CFB\u3002</p><button class=\"command secondary\" data-action=\"device-take\">\u8BA9\u8FD9\u53F0\u7535\u8111\u8D1F\u8D23\u4E3B\u52A8\u53D1\u9001</button></details></section>\n<section id=\"computer-panel\"><h2>\u611F\u77E5\u7535\u8111\u53D1\u751F\u7684\u4E8B</h2><label><input id=\"computer-enabled\" type=\"checkbox\">\u542F\u7528\u7535\u8111\u4E8B\u4EF6\u611F\u77E5</label><div class=\"grid\"><label><input id=\"computer-apps\" type=\"checkbox\">\u524D\u53F0\u5E94\u7528\u5207\u6362\uFF08\u8FDB\u7A0B\u540D\uFF09</label><label><input id=\"computer-network\" type=\"checkbox\">\u7F51\u7EDC\u6062\u590D</label><label><input id=\"computer-resources\" type=\"checkbox\">\u7535\u91CF\u4E0E\u8D44\u6E90\u5F02\u5E38</label><label>\u7A7A\u95F2\u591A\u4E45\u540E\u8FD4\u56DE\u89C6\u4E3A\u65B0\u4E8B\u4EF6\uFF08\u5206\u949F\uFF09<input id=\"idle-minutes\" type=\"number\" min=\"1\" max=\"1440\"></label></div><label>\u7559\u610F\u8FD9\u4E9B\u6587\u4EF6\u5939\u7684\u53D8\u5316\uFF08\u6BCF\u884C\u4E00\u4E2A\u5B8C\u6574\u8DEF\u5F84\uFF0C\u6700\u591A 8 \u4E2A\uFF09<textarea id=\"watch-directories\" placeholder=\"\u4F8B\u5982\u4E0B\u8F7D\u76EE\u5F55\uFF0C\u7559\u7A7A\u5219\u4E0D\u76D1\u542C\u6587\u4EF6\u5939\"></textarea></label><p class=\"muted\">\u53EA\u8BB0\u5F55\u72B6\u6001\u3001\u5E94\u7528\u8FDB\u7A0B\u540D\u548C\u6307\u5B9A\u76EE\u5F55\u7684\u6587\u4EF6\u540D\u3002\u5C4F\u5E55\u3001\u7A97\u53E3\u6807\u9898\u3001\u952E\u76D8\u3001\u526A\u8D34\u677F\u548C\u6587\u4EF6\u6B63\u6587\u4E0D\u5728\u91C7\u96C6\u8303\u56F4\u3002\u4E8B\u4EF6\u4E0D\u4F1A\u4F5C\u4E3A\u7528\u6237\u8BF4\u8FC7\u7684\u8BDD\u5199\u5165\u8BB0\u5FC6\u3002</p><pre id=\"computer-status\"></pre><div id=\"computer-events\"></div><button class=\"command secondary\" data-action=\"computer-clear\">\u64A4\u9500\u7535\u8111\u4E8B\u4EF6\u8BDD\u9898</button><p class=\"muted\">\u4FEE\u6539\u540E\u70B9\u51FB\u4E0A\u65B9\u201C\u4FDD\u5B58\u4E3B\u52A8\u8054\u7CFB\u4E0E\u7535\u8111\u611F\u77E5\u8BBE\u7F6E\u201D\u3002</p></section>\n<section id=\"personality-panel\"><h2>\u6027\u683C\u4E0E\u4EA4\u6D41\u4E60\u60EF</h2><div class=\"grid\"><label>\u57FA\u7840\u6027\u683C<select id=\"personality-preset\"><option value=\"balanced\">\u5747\u8861</option><option value=\"gentle\">\u6E29\u548C</option><option value=\"irritable\">\u76F4\u7387\u654F\u611F</option></select></label><div><button id=\"set-preset\">\u5E94\u7528\u57FA\u7840\u6027\u683C</button></div></div><div id=\"trait-inputs\" class=\"grid\"></div><button id=\"set-traits\">\u4FDD\u5B58\u6027\u683C\u7EF4\u5EA6</button><details><summary>\u7EC4\u5408\u6027\u683C\u6A21\u677F</summary><div id=\"mix-inputs\" class=\"grid\"></div><button id=\"set-mix\">\u5E94\u7528\u6A21\u677F\u7EC4\u5408</button></details><h3>\u5B66\u5230\u7684\u4EA4\u6D41\u4E60\u60EF</h3><div id=\"habit-list\"></div></section>\n<section id=\"memory-panel\"><h2>\u8BB0\u5FC6\u4E0E\u66F4\u6B63</h2><label>\u67E5\u627E\u8BB0\u5FC6<input id=\"memory-query\" placeholder=\"\u8F93\u5165\u5173\u952E\u8BCD\"></label><button id=\"memory-search\">\u67E5\u627E</button><div id=\"memory-list\"></div><label>\u5E0C\u671B\u8BB0\u4F4F\u7684\u5185\u5BB9<textarea id=\"remember-text\"></textarea></label><button id=\"remember\">\u4FDD\u5B58\u4E00\u6761\u8BB0\u5FC6</button><details><summary>\u7EA0\u6B63\u60C5\u7EEA\u5224\u65AD</summary><label>\u9009\u62E9\u6700\u8FD1\u7684\u5224\u65AD<select id=\"correct-event\"></select></label><label>\u4E8B\u4EF6\u5E8F\u53F7<input id=\"correct-sequence\" type=\"number\" min=\"1\"></label><label>\u6B63\u786E\u89E3\u91CA<textarea id=\"correct-text\"></textarea></label><button id=\"correct\">\u4FDD\u5B58\u66F4\u6B63</button></details><details><summary>\u66F4\u6B63\u4E3B\u52A8\u8054\u7CFB\u7684\u53CD\u9988\u5224\u65AD</summary><label>\u53CD\u9988\u8BB0\u5F55<select id=\"feedback-record\"></select></label><label>\u5B9E\u9645\u53CD\u9988<select id=\"feedback-kind\"><option value=\"positive\">\u559C\u6B22\u8FD9\u6B21\u8054\u7CFB</option><option value=\"negative\">\u4E0D\u559C\u6B22\u8FD9\u6B21\u8054\u7CFB</option><option value=\"busy\">\u5F53\u65F6\u5728\u5FD9</option><option value=\"unrelated\">\u56DE\u590D\u4E0E\u4E3B\u52A8\u8BDD\u9898\u65E0\u5173</option><option value=\"unknown\">\u65E0\u6CD5\u5224\u65AD</option><option value=\"explicit_preference\">\u660E\u786E\u8868\u8FBE\u4E86\u8054\u7CFB\u504F\u597D</option></select></label><button id=\"feedback-correct\">\u4FDD\u5B58\u53CD\u9988\u66F4\u6B63</button></details></section>\n<section id=\"tasks-panel\"><h2>\u63D0\u9192\u4E0E\u5F85\u7EED\u4E8B\u9879</h2><div class=\"grid\"><label>\u63D0\u9192\u5185\u5BB9<input id=\"reminder-text\"></label><label>\u63D0\u9192\u65F6\u95F4<input id=\"reminder-time\" type=\"datetime-local\"></label></div><button id=\"reminder-add\">\u6DFB\u52A0\u63D0\u9192</button><div id=\"task-list\"></div></section>\n<section id=\"maintenance-panel\"><h2>\u5907\u4EFD\u3001\u6574\u7406\u4E0E\u8BCA\u65AD</h2><button class=\"command\" data-action=\"backup\">\u7ACB\u5373\u5907\u4EFD</button><button class=\"command secondary\" data-action=\"background-pause\">\u6682\u505C\u540E\u53F0\u6574\u7406</button><button class=\"command secondary\" data-action=\"background-resume\">\u6062\u590D\u540E\u53F0\u6574\u7406</button><button class=\"command secondary\" data-action=\"doctor\">\u8FD0\u884C\u81EA\u68C0</button><pre id=\"maintenance-status\"></pre><details><summary>\u8868\u8FBE\u68C0\u67E5\u8BB0\u5F55</summary><div id=\"expression-list\"></div></details><details><summary>\u9694\u79BB\u8BD5\u804A\u573A\u666F</summary><label>\u6D4B\u8BD5\u573A\u666F<select id=\"review-fixture\"><option value=\"friendly\">\u53CB\u597D</option><option value=\"tense\">\u7D27\u5F20</option><option value=\"after_conflict\">\u51B2\u7A81\u4E4B\u540E</option></select></label><button id=\"review-begin\">\u8FDB\u5165\u9694\u79BB\u6D4B\u8BD5</button><button class=\"command secondary\" data-action=\"review-end\">\u7ED3\u675F\u9694\u79BB\u6D4B\u8BD5</button></details><details><summary>\u91CD\u7F6E\u5173\u7CFB</summary><p>\u5C06\u5F53\u524D\u89D2\u8272\u7684\u5173\u7CFB\u72B6\u6001\u5F52\u96F6\uFF0C\u8BB0\u5FC6\u4ECD\u4FDD\u7559\u3002</p><button class=\"command danger\" data-action=\"reset-relationship\">\u786E\u8BA4\u540E\u91CD\u7F6E\u5173\u7CFB</button></details></section>";
export declare const panelScript = "\nconst traitLabels={irritability:'\u6613\u6012',sensitivity:'\u654F\u611F',directness:'\u76F4\u7387',selfControl:'\u81EA\u63A7',warmth:'\u6E29\u6696',initiative:'\u4E3B\u52A8',socialEnergy:'\u793E\u4EA4\u6D3B\u529B',playfulness:'\u6D3B\u6CFC',reserve:'\u542B\u84C4',conscientiousness:'\u8BA4\u771F',curiosity:'\u597D\u5947',optimism:'\u4E50\u89C2'},templateLabels={tsundere:'\u50B2\u5A07',earnest:'\u8BA4\u771F',wilful:'\u4EFB\u6027',gentle:'\u6E29\u67D4',playful:'\u6D3B\u6CFC',innocent:'\u5929\u771F',reserved:'\u5185\u655B',candid:'\u5766\u7387'};\nlet panelLoaded=false,panelDirty=false,panelData=null;\nfunction lines(id){return $(id).value.split(/\\r?\\n/).map(s=>s.trim()).filter(Boolean)}\nfunction options(id,rows,value,label){const box=$(id),selected=box.value;box.replaceChildren();for(const row of rows){const option=document.createElement('option');option.value=String(value(row));option.textContent=label(row);box.append(option)}if(rows.some(row=>String(value(row))===selected))box.value=selected}\nfunction list(id,rows,describe,button){const box=$(id);box.replaceChildren();if(!rows.length){const p=document.createElement('p');p.className='muted';p.textContent='\u6682\u65E0\u8BB0\u5F55';box.append(p);return}for(const row of rows){const div=document.createElement('div');div.className='item';const p=document.createElement('p');p.textContent=describe(row);div.append(p);if(button){const spec=button(row);if(spec){const b=document.createElement('button');b.className='secondary';b.textContent=spec.label;b.onclick=()=>run(()=>panelAction(spec.action,spec.body));div.append(b)}}box.append(div)}}\nfunction showResult(value){const box=$('panel-result');box.hidden=false;box.textContent=typeof value.text==='string'?value.text:JSON.stringify(value,null,2);$('message').textContent=value.kind==='error'?value.text:'\u64CD\u4F5C\u5DF2\u5B8C\u6210\u3002'}\nasync function panelAction(action,body={}){const destructive=['forget','reset-relationship','device-take'].includes(action);if(destructive&&!window.confirm(action==='forget'?'\u786E\u8BA4\u5FD8\u6389\u8FD9\u6761\u8BB0\u5FC6\uFF1F':action==='device-take'?'\u5DF2\u5728\u65E7\u7535\u8111\u6682\u505C\u4E3B\u52A8\u8054\u7CFB\uFF0C\u786E\u8BA4\u7531\u672C\u673A\u63A5\u7BA1\uFF1F':'\u786E\u8BA4\u91CD\u7F6E\u5F53\u524D\u89D2\u8272\u7684\u5173\u7CFB\uFF1F'))return;const value=await request('panel-action',{action,conversationId:$('panel-conversation').value||undefined,...body,...(destructive?{confirmed:true}:{})});showResult(value);if(['settings','personality-preset','personality-mix','personality-set'].includes(action)){panelLoaded=false;panelDirty=false}await refreshPanel()}\nasync function refreshPanel(){const selected=$('panel-conversation').value||'',query=$('memory-query').value||'';const s=await request('panel?conversationId='+encodeURIComponent(selected)+'&query='+encodeURIComponent(query));panelData=s;\nconst choose=$('panel-conversation');if(!panelLoaded){choose.replaceChildren();for(const row of s.conversations){const option=document.createElement('option');option.value=row.id;option.textContent=row.label+(row.available?' \u00B7 \u53EF\u8054\u7CFB':'');choose.append(option)}choose.value=s.selected}\nconst rel=s.state.relationship,mood=s.state.mood;$('panel-summary').textContent='\u597D\u611F '+Math.round(rel.affection*100)+'% \u00B7 \u4FE1\u4EFB '+Math.round(rel.trust*100)+'% \u00B7 \u719F\u6089 '+Math.round(rel.familiarity*100)+'%\\n\u5FC3\u60C5\uFF1A\u559C\u60A6 '+Math.round(mood.joy*100)+'% \u00B7 \u7D27\u5F20 '+Math.round(mood.tension*100)+'%\\n\u8BB0\u5FC6 '+(s.runtime.counts.memories||0)+' \u6761 \u00B7 \u539F\u6587 '+(s.runtime.counts.raw_messages||0)+' \u6761';\nconst reasons={'proactive-disabled':'\u4E3B\u52A8\u8054\u7CFB\u5DF2\u6682\u505C','inactive-device':'\u7531\u53E6\u4E00\u53F0\u7535\u8111\u8D1F\u8D23\u4E3B\u52A8\u53D1\u9001','quiet-hours':'\u73B0\u5728\u5904\u4E8E\u9759\u9ED8\u65F6\u6BB5','main-turn-in-flight':'\u6B63\u5728\u5BF9\u8BDD','user-busy':'\u4F60\u8868\u793A\u6B63\u5728\u5FD9','daily-limit':'\u8FBE\u5230\u4ECA\u65E5\u8054\u7CFB\u989D\u5EA6','global-daily-limit':'\u8FBE\u5230\u4ECA\u65E5\u603B\u989D\u5EA6','cooldown':'\u8FD8\u5728\u8054\u7CFB\u95F4\u9694\u5185','awaiting-reply':'\u4E0A\u4E00\u6761\u4E3B\u52A8\u6D88\u606F\u5C1A\u672A\u83B7\u56DE\u590D'};\n$('proactive-explanation').textContent=s.proactive.enabled?(s.gates.ok?'\u4E3B\u52A8\u8054\u7CFB\u5DF2\u5F00\u542F\uFF0C\u4F1A\u7B49\u5F85\u5408\u9002\u7684\u771F\u5B9E\u8BDD\u9898\u3002':s.gates.blocked.map(x=>reasons[x]||x).join('\uFF1B')):'\u4E3B\u52A8\u8054\u7CFB\u76EE\u524D\u5DF2\u6682\u505C\u3002';$('frequency-explanation').textContent='\u5F53\u524D\u89D2\u8272\u7684\u5B9E\u9645\u989D\u5EA6\uFF1A\u6BCF\u5929\u6700\u591A '+s.frequency.dailyLimit+' \u6761\uFF0C\u81F3\u5C11\u95F4\u9694 '+s.frequency.minGapMinutes+' \u5206\u949F\u3002\\n'+s.frequency.reason;\nif(!panelLoaded&&!panelDirty){const p=s.proactive,c=s.computer.settings;for(const [id,key]of Object.entries({'daily-limit':'spontaneousLimitPerDay','min-gap':'spontaneousMinGapMinutes','check-minutes':'checkMinutes','unanswered':'pauseAfterUnanswered','quiet-start':'quietStart','quiet-end':'quietEnd','adaptive-max':'adaptiveMaxDailyLimit','adaptive-gap':'adaptiveMinGapMinutes'}))$(id).value=p[key];$('adaptive').checked=p.adaptiveFrequency;$('model-interests').value=p.modelInterests.join('\\n');$('share-sources').value=p.shareSources.join('\\n');$('computer-enabled').checked=c.enabled;$('computer-apps').checked=c.foregroundApplications;$('computer-network').checked=c.network;$('computer-resources').checked=c.resources;$('idle-minutes').value=c.idleThresholdSeconds/60;$('watch-directories').value=c.watchDirectories.join('\\n');\nconst traitBox=$('trait-inputs');traitBox.replaceChildren();for(const[key,label]of Object.entries(traitLabels)){const l=document.createElement('label'),i=document.createElement('input');l.textContent=label;i.type='number';i.min='0';i.max='1';i.step='.05';i.id='trait-'+key;i.value=(s.profile?.traits?.[key]??s.state.personality[key]??.5);l.append(i);traitBox.append(l)}const mixBox=$('mix-inputs');mixBox.replaceChildren();for(const[key,label]of Object.entries(templateLabels)){const l=document.createElement('label'),i=document.createElement('input');l.textContent=label+'\u6743\u91CD';i.type='number';i.min='0';i.step='.1';i.id='mix-'+key;i.value=s.profile?.templates?.find(x=>x.id===key)?.weight??0;l.append(i);mixBox.append(l)}}\n$('computer-status').textContent=s.computer.settings.enabled?('\u91C7\u96C6\u72B6\u6001\uFF1A'+(s.computer.status.sampling?'\u8BFB\u53D6\u4E2D':s.computer.status.error||'\u5DF2\u542F\u7528')+'\\n\u6700\u8FD1\u91C7\u6837\uFF1A'+(s.computer.status.lastSampleAtMs?new Date(s.computer.status.lastSampleAtMs).toLocaleString():'\u5C1A\u65E0')):'\u7535\u8111\u4E8B\u4EF6\u611F\u77E5\u5C1A\u672A\u5F00\u542F\u3002';\noptions('correct-event',s.events.filter(e=>e.status==='active'),e=>e.seq,e=>'#'+e.seq+' \u00B7 '+e.payload_json.slice(0,150));options('feedback-record',s.feedback,e=>e.id,e=>e.kind+' \u00B7 '+(e.evidence_quote||'\u672A\u8BF4\u660E'));if(!$('correct-sequence').value)$('correct-sequence').value=$('correct-event').value;\nlist('computer-events',s.computer.recent,e=>new Date(e.occurredAtMs).toLocaleTimeString()+' \u00B7 '+e.summary);list('memory-list',s.memories,m=>m.claim,m=>({label:'\u5FD8\u6389',action:'forget',body:{id:m.id}}));list('habit-list',s.habits,h=>h.kind+' \u00B7 '+h.value_json+' \u00B7 '+h.status,h=>h.status==='active'?{label:'\u64A4\u9500\u4E60\u60EF',action:'habit-forget',body:{id:h.id}}:null);list('task-list',s.tasks,t=>t.content+' \u00B7 '+t.status+(t.due_at_ms?' \u00B7 '+new Date(t.due_at_ms).toLocaleString():''),t=>['proposed','confirmed'].includes(t.status)?{label:'\u53D6\u6D88',action:'task-cancel',body:{id:t.id}}:null);list('opportunity-list',s.opportunities,o=>o.summary+' \u00B7 '+o.status);list('expression-list',s.expression,e=>e.status+' \u00B7 '+e.issues_json);$('maintenance-status').textContent='\u5907\u4EFD '+s.backups.total+' \u4EFD\\n\u540E\u53F0\u6574\u7406\uFF1A'+JSON.stringify(s.background);panelLoaded=true;}\nfor(const b of document.querySelectorAll('.command'))b.onclick=()=>run(()=>panelAction(b.dataset.action));\n$('correct-event').onchange=()=>{$('correct-sequence').value=$('correct-event').value};$('feedback-correct').onclick=()=>run(()=>panelAction('feedback-correct',{id:$('feedback-record').value,kind:$('feedback-kind').value}));\n$('panel-conversation').onchange=()=>run(async()=>{panelLoaded=false;panelDirty=false;await refreshPanel()});$('memory-search').onclick=()=>run(refreshPanel);\n$('save-settings').onclick=()=>run(()=>panelAction('settings',{settings:{proactive:{spontaneousLimitPerDay:Number($('daily-limit').value),spontaneousMinGapMinutes:Number($('min-gap').value),checkMinutes:Number($('check-minutes').value),pauseAfterUnanswered:Number($('unanswered').value),quietStart:$('quiet-start').value,quietEnd:$('quiet-end').value,adaptiveFrequency:$('adaptive').checked,adaptiveMaxDailyLimit:Number($('adaptive-max').value),adaptiveMinGapMinutes:Number($('adaptive-gap').value),modelInterests:lines('model-interests'),shareSources:lines('share-sources')},computerEvents:{enabled:$('computer-enabled').checked,foregroundApplications:$('computer-apps').checked,network:$('computer-network').checked,resources:$('computer-resources').checked,idleThresholdSeconds:Number($('idle-minutes').value)*60,watchDirectories:lines('watch-directories')}}}));\n$('set-preset').onclick=()=>run(()=>panelAction('personality-preset',{preset:$('personality-preset').value}));$('set-traits').onclick=()=>run(()=>panelAction('personality-set',{traits:Object.fromEntries(Object.keys(traitLabels).map(key=>[key,Number($('trait-'+key).value)]))}));$('set-mix').onclick=()=>run(()=>panelAction('personality-mix',{mix:Object.fromEntries(Object.keys(templateLabels).map(key=>[key,Number($('mix-'+key).value)]).filter(([,value])=>value>0))}));$('remember').onclick=()=>run(()=>panelAction('remember',{text:$('remember-text').value}));$('correct').onclick=()=>run(()=>panelAction('correct',{sequence:Number($('correct-sequence').value),text:$('correct-text').value}));$('reminder-add').onclick=()=>run(()=>panelAction('task-add',{text:$('reminder-text').value,dueAtMs:new Date($('reminder-time').value).getTime()}));$('review-begin').onclick=()=>run(()=>panelAction('review-begin',{fixture:$('review-fixture').value}));\nfor(const e of document.querySelectorAll('#proactive-panel input,#proactive-panel textarea,#computer-panel input,#computer-panel textarea'))e.addEventListener('input',()=>{panelDirty=true});\nrefreshPanel().catch(e=>{$('message').textContent=e.message});";
